sed -i "s/import { Privacy } from '.\/view\/pages\/Privacy';/import { Privacy } from '.\/view\/pages\/Privacy';\nimport { Rankings } from '.\/view\/pages\/Rankings';\nimport { ComparePage } from '.\/view\/pages\/ComparePage';/" src/App.tsx
